    srows=[r for r in range(H) if len(set(I_[r]))==1 and I_[r][0]!=bg]
    scols=[c for c in range(W) if len({I_[r][c] for r in range(H)})==1 and I_[0][c]!=bg]
    def grouper(lst):
        out=[];cur=[]
        for p in lst:
            if cur and p==cur[-1]+1: cur.append(p)
            else:
                if cur: out.append(tuple(cur)); cur=[p]
        if cur: out.append(tuple(cur))
        return out
    rb=grouper([r for r in range(H) if r not in srows]); cb=grouper([c for c in range(W) if c not in scols])
    res=[]
    for R in rb:
        for C in cb:
            pts=[(i_,j_) for i_ in range(R[0],R[-1]+1) for j_ in range(C[0],C[-1]+1) if I_[i_][j_]==mark]
            S=set(pts); P=set()
            for x,y in pts:
                if (x+1,y) in S or (x-1,y) in S or (x,y+1) in S or (x,y-1) in S: P.add((x,y))
            hpair=sum(1 for (x,y) in P if (x+1,y) in S); vpair=sum(1 for (x,y) in P if (x,y+1) in S)
            junc=sum(1 for (x,y) in pts if (x+1,y) in S and (x,y+1) in S)+sum(1 for (x,y) in pts if (x-1,y) in S and (x,y-1) in S)
            fill=all(O_[i_][j_]==mark for i_ in range(R[0],R[-1]+1) for j in range(C[0],C[-1]+1))
            rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
            area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
            res.append((R,C,len(pts),fill,hpair,vpair,junc,area,len(S)))
    return res
