def info(I_,O_,mark):
    H,W=len(I_),len(I_[0])
    cnt=Counter(v for row_ in I_ for v in row_)
    bg=cnt.most_common(1)[0][0]
    sep=[v for v,cn in cnt.items() if v!=bg][0]
    srows=[r for r in range(H) if all(v==sep for v in I_[r])]
    scols=[c for c in range(W) if all(I_[r][c]==sep for r in range(H))]
    def grouper(lst):
        out=[];cur=[]
        for p in lst:
            if cur and p==cur[-1]+1: cur.append(p)
            else:
                if cur: out.append(tuple(cur)); cur=[p]
        if cur: out.append(tuple(cur))
        return out
    rb=grouper([r for r in range(H) if r not in srows]); cb=grouper([c for c in range(W) if c not in scols])
    res=[]
    for R in rb:
        for C in cb:
            pts=[(i_,j) for i_ in range(R[0],R[-1]+1) for j in range(C[0],C[-1]+1) if I_[i_][j]==mark]
            S=set(pts)
            fill=all(O_[i_][j_]==mark for i_ in range(R[0],R[-1]+1) for j in range(C[0],C[-1]+1))
            rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
            area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1) if pts else 0
            # connected components
            seen=set(); comps=[]
            for p in pts:
                if p in seen: continue
                st=[p];seen.add(p);comp=[]
                while st:
                    x,y=st.pop();comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(x+dx,y+dy)
                        if q in S and q not in seen: seen.add(q);st.append(q)
                comps.append(comp)
            big=max(comps,key=len)
            mx=max(len(c) for c in comps)
            # adjacency pairs within bbox
            adj=sum(1 for (x,y) in pts if (x+1,y) in S)+(sum(1 for (x,y) in pts if (x,y+1) in S))
            res.append((R,C,len(pts),fill,mx,adj,len(big),area,len(S)))
    return res
